import { loadFont } from "@remotion/google-fonts/BreeSerif";
import { Audio } from "@remotion/media";
import {
  AbsoluteFill,
    Sequence,
      staticFile,
        useVideoConfig,
        } from "remotion";
        import { z } from "zod";

        import { FPS, INTRO_DURATION } from "../lib/constants";
        import { TimelineSchema } from "../lib/types";
        import { calculateFrameTiming, getAudioPath } from "../lib/utils";

        import { Background } from "./Background-old";
        import { Scene } from "./Scene";
        import Subtitle from "./Subtitle";

        export const aiVideoSchema = z.object({
          timeline: TimelineSchema.nullable(),
          });

          const { fontFamily } = loadFont();

          export const AIVideo: React.FC<z.infer<typeof aiVideoSchema>> = ({
            timeline,
            }) => {
              if (!timeline) {
                  throw new Error("Expected timeline to be fetched");
                    }

                      const { id } = useVideoConfig();

                        const hasNewScenes =
                            timeline.scenes !== undefined && timeline.scenes.length > 0;

                              return (
                                  <AbsoluteFill
                                        style={{
                                                backgroundColor: "white",
                                                      }}
                                                          >
                                                                {/* INTRO */}
                                                                      <Sequence durationInFrames={INTRO_DURATION}>
                                                                              <AbsoluteFill
                                                                                        style={{
                                                                                                    justifyContent: "center",
                                                                                                                alignItems: "center",
                                                                                                                            textAlign: "center",
                                                                                                                                        display: "flex",
                                                                                                                                                    zIndex: 10,
                                                                                                                                                              }}
                                                                                                                                                                      >
                                                                                                                                                                                <div
                                                                                                                                                                                            style={{
                                                                                                                                                                                                          fontSize: 120,
                                                                                                                                                                                                                        lineHeight: "122px",
                                                                                                                                                                                                                                      width: "87%",
                                                                                                                                                                                                                                                    color: "black",
                                                                                                                                                                                                                                                                  fontFamily,
                                                                                                                                                                                                                                                                                textTransform: "uppercase",
                                                                                                                                                                                                                                                                                              backgroundColor: "yellow",
                                                                                                                                                                                                                                                                                                            paddingTop: 20,
                                                                                                                                                                                                                                                                                                                          paddingBottom: 20,
                                                                                                                                                                                                                                                                                                                                        border: "10px solid black",
                                                                                                                                                                                                                                                                                                                                                    }}
                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                          {timeline.shortTitle}
                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                            </AbsoluteFill>
                                                                                                                                                                                                                                                                                                                                                                                                  </Sequence>

                                                                                                                                                                                                                                                                                                                                                                                                        {/* NEW SCENE SYSTEM */}
                                                                                                                                                                                                                                                                                                                                                                                                              {hasNewScenes &&
                                                                                                                                                                                                                                                                                                                                                                                                                      timeline.scenes?.map((scene, index) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                const { startFrame, duration } = calculateFrameTiming(
                                                                                                                                                                                                                                                                                                                                                                                                                                            scene.startMs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                        scene.endMs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  addIntroOffset: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Sequence
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            key={`scene-${scene.id}-${index}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          from={startFrame}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        durationInFrames={duration}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      premountFor={3 * FPS}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Scene scene={scene} project={id} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </Sequence>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              })}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {/* OLD BACKGROUND SYSTEM */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {!hasNewScenes &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  timeline.elements.map((element, index) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const { startFrame, duration } = calculateFrameTiming(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        element.startMs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    element.endMs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              includeIntro: index === 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Sequence
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        key={`element-${index}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      from={startFrame}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    durationInFrames={duration}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  premountFor={3 * FPS}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Background project={id} item={element} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Sequence>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          })}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {/* SUBTITLES */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {timeline.text.map((element, index) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const { startFrame, duration } = calculateFrameTiming(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        element.startMs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  element.endMs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        addIntroOffset: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Sequence
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        key={`subtitle-${index}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    from={startFrame}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                durationInFrames={duration}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Subtitle text={element.text} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </Sequence>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              })}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {/* AUDIO / NARRATION */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {timeline.audio.map((element, index) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const { startFrame, duration } = calculateFrameTiming(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            element.startMs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      element.endMs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            addIntroOffset: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Sequence
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            key={`audio-${index}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        from={startFrame}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    durationInFrames={duration}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                premountFor={3 * FPS}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Audio
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    src={staticFile(getAudioPath(id, element.audioUrl))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </Sequence>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </AbsoluteFill>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              };